/* ═══════════════════════════════════════
   키오스크 기본형 — 기본 제공 문구의 14개국어 번역 + phrase 빌더·번역 조회
   ═══════════════════════════════════════
   한국어 원문(텍스트)을 키로 사용 → phrase key 인덱스가 바뀌어도 안전.
   사용자가 직접 입력한 번역(ks.translations[lang][key])이 있으면 그것이 우선,
   없으면 이 기본 번역이 붙여넣기 모달의 입력란에 표시된다.
   언어 코드: en zh ja vi th tl km mn ru ne id ar ur es

   ※ phrase 빌더(kioskBuildTransPhrases)·번역 조회(kioskGetTrans)를 이 모듈에 둔 이유:
     kiosk-html-builder 가 kiosk-translation 을 import 하면 순환참조
     (kiosk-html-builder→kiosk-translation→settings-view→kiosk-cms-view→kiosk-html-builder)가
     생기므로, 의존성이 app-state 뿐인 이 모듈로 분리해 순환을 끊는다. */
import { S } from '../../core/app-state.js';
const _ks = S.kioskSettings;

/* 사용자 저장 번역 조회. 키는 "한국어 원문"(trim) — 원문을 바꾸면 옛 키가 고아가 되어 빈 문자열을 돌려준다. */
export function kioskGetTrans(langCode, key){
  const k = (key||'').trim();
  return (_ks.translations && _ks.translations[langCode] && _ks.translations[langCode][k]) || '';
}

/* ── 학교 환경 검출 — 인적사항 조건부 phrase 생성 ── */
function _getDetectedLevels(){
  const set = new Set();
  (S.people||[]).forEach(function(p){ if(p.type==='student' && p.level) set.add(p.level); });
  return Array.from(set);
}
function _hasDepartments(){
  return (S.people||[]).some(function(p){ return p.type==='student' && p.department; });
}
function _getDepartmentNames(){
  const set = new Set();
  (S.people||[]).forEach(function(p){ if(p.type==='student' && p.department) set.add(p.department); });
  return Array.from(set);
}
const _LEVEL_LABELS = {
  'kindergarten':'유치원','유':'유치원',
  'elementary':'초등학교','초':'초등학교',
  'middle':'중학교','중':'중학교',
  'high':'고등학교','고':'고등학교',
  'university':'대학교','대':'대학교',
  'special':'특수학교'
};
function _levelLabel(code){ return _LEVEL_LABELS[code] || code; }

/* ── phrase 빌더 — 한국어 문장을 [{section, items:[{key,ko}]}] 로 반환 ── */
export function kioskBuildTransPhrases(flow, rules){
  const phrases = [];
  /* 1. 인적사항 화면 */
  const detectedLevels = _getDetectedLevels();
  const multiLevel = detectedLevels.length > 1;
  const hasDept = _hasDepartments();
  const deptNames = hasDept ? _getDepartmentNames() : [];
  const person = [
    {key:'person.heading',   ko:'방문자를 선택해주세요.'},
    {key:'person.tab.stu',   ko:'학생'},
    {key:'person.tab.staff', ko:'교직원'},
  ];
  if(multiLevel){
    person.push({key:'person.levelLabel', ko:'학교급'});
    detectedLevels.forEach(function(lv){ person.push({key:'person.level.'+lv, ko:_levelLabel(lv)}); });
  }
  person.push({key:'person.gradeLabel', ko:'학년'}, {key:'person.classLabel', ko:'반'});
  if(hasDept){
    person.push({key:'person.deptLabel', ko:'학과'});
    /* 학과명(항공기계과 등)은 학교별 고유명사 — 번역 대상에서 제외, 키오스크는 원문 그대로 표시 (사용자 요청 2026-06-14) */
  }
  person.push({key:'person.nameLabel', ko:'이름'}, {key:'person.confirmBtn', ko:'확인'}, {key:'person.backBtn', ko:'뒤로'});
  phrases.push({section:'인적사항 화면', items:person});
  /* 2. 이용 수칙 */
  const r = rules || {};
  const ruleItems = [];
  if(r.title)     ruleItems.push({key:'rule.title',     ko:r.title});
  if(r.timeTitle) ruleItems.push({key:'rule.timeTitle', ko:r.timeTitle});
  (r.time||[]).forEach(function(t, i){
    if(t && (typeof t==='string' ? t.trim() : (t.text && t.text.trim())))
      ruleItems.push({key:'rule.time.'+i, ko:typeof t==='string' ? t : t.text});
  });
  if(r.mannerTitle) ruleItems.push({key:'rule.mannerTitle', ko:r.mannerTitle});
  (r.manners||[]).forEach(function(m, i){
    const txt = typeof m==='string' ? m : (m.text||'');
    if(txt && txt.trim()) ruleItems.push({key:'rule.manner.'+i, ko:txt});
  });
  (r.extraSections||[]).forEach(function(sec, si){
    if(sec.title) ruleItems.push({key:'rule.extra.'+si+'.title', ko:sec.title});
    (sec.items||[]).forEach(function(it, ii){
      const txt = typeof it==='string' ? it : (it.text||'');
      if(txt && txt.trim()) ruleItems.push({key:'rule.extra.'+si+'.item.'+ii, ko:txt});
    });
  });
  if(ruleItems.length) phrases.push({section:'이용 수칙', items:ruleItems});
  /* 3. 플로우 */
  const flowSections = (flow && flow.sections) || [];
  const flowItems = [];
  flowSections.forEach(function(sec){
    if(sec.headerName) flowItems.push({key:'flow.'+sec.id+'.header', ko:sec.headerName});
    (sec.options||[]).forEach(function(opt, oi){
      if(opt.label) flowItems.push({key:'flow.'+sec.id+'.opt.'+oi, ko:opt.label});
      /* 항목별 커스텀 안내문/완료문도 번역 대상 — 렌더는 _t() 로 함. 기본 메시지는 기본번역, 사용자 커스텀은 붙여넣기 모달에서 입력 (사용자 요청 2026-06-14) */
      if(opt.guideMsg && String(opt.guideMsg).trim()) flowItems.push({key:'flow.'+sec.id+'.opt.'+oi+'.guide', ko:String(opt.guideMsg).trim()});
      if(opt.doneMsg && String(opt.doneMsg).trim()) flowItems.push({key:'flow.'+sec.id+'.opt.'+oi+'.done', ko:String(opt.doneMsg).trim()});
    });
    if(sec.type==='guide' && sec.guideText && sec.guideText.trim())
      flowItems.push({key:'flow.'+sec.id+'.guide', ko:sec.guideText});
  });
  if(flowItems.length) phrases.push({section:'플로우 — 단계·버튼·안내', items:flowItems});
  /* 4. 상비약·물품 */
  const supplyArr = _ks.supplyItems || ['생리대','면봉','마스크','대역 밴드','손 소독제'];
  const supplyItems = supplyArr.map(function(it, i){
    const nm = typeof it==='string' ? it : (it.name || '');
    return nm ? {key:'supply.'+i, ko:nm} : null;
  }).filter(Boolean);
  if(supplyItems.length) phrases.push({section:'상비약·물품', items:supplyItems});
  /* 5. 자가 처치 안내 */
  const guides = _ks.selfCareGuides || [];
  const guideItems = [];
  guides.forEach(function(g, i){
    if(g.title) guideItems.push({key:'guide.'+i+'.title', ko:g.title});
    const body = g.guide || g.description;
    if(body) guideItems.push({key:'guide.'+i+'.body', ko:body});
  });
  if(guideItems.length) phrases.push({section:'자가 처치 안내', items:guideItems});
  /* 6. 방문자 순번 안내 + 대기 카드 (고정) */
  phrases.push({section:'방문자 순번·대기 안내', items:[
    {key:'queue.heading',   ko:'방문자 순번 안내'},
    {key:'queue.waiting',   ko:'현재 대기 중인 학생'},
    {key:'queue.curCount',  ko:'현재 대기 인원'},
    {key:'queue.empty',     ko:'대기 중인 방문자가 없습니다'},
    {key:'queue.unit',      ko:'명'},
    {key:'queue.startBtn',  ko:'등록 시작'},
  ]});

  /* 7. 키오스크 고정 문구·버튼 (안내문 + 네비 버튼 + 완료 화면 + 바디맵 모달 + 접수 팝업) */
  phrases.push({section:'키오스크 고정 문구·버튼', items:[
    {key:'notice.intro',     ko:'보건실은 아픈 친구들을 위한 공간입니다. 서로 배려하며 조용히 이용합시다.'},
    {key:'nav.home',         ko:'처음으로'},
    {key:'done.complete',    ko:'접수가 완료되었습니다.'},
    /* 바디맵 모달 문구 (부위명 제외) */
    {key:'bm.title',  ko:'바디맵 — 통증 부위 선택'},
    {key:'bm.sub',    ko:'터치: 부위 선택 · 마커 터치: 통증 척도(NRS)'},
    {key:'bm.cancel', ko:'취소'},
    {key:'bm.hint',   ko:'선택된 부위가 여기에 표시됩니다'},
    {key:'bm.left',   ko:'왼쪽'},
    {key:'bm.right',  ko:'오른쪽'},
    /* NRS(통증 척도) 팝업 */
    {key:'nrs.title',  ko:'통증 척도 (NRS)'},
    {key:'nrs.sub',    ko:'부위의 통증 정도를 선택하세요'},
    {key:'nrs.none',   ko:'통증 없음'},
    {key:'nrs.severe', ko:'극심한 통증'},
    /* 접수 팝업 (JS 동적 메시지) */
    {key:'done.label',    ko:'완료'},
    {key:'done.thanks',   ko:'감사합니다. 처음 화면으로 돌아갑니다.'},
    {key:'done.received', ko:'접수되었습니다.'},
    {key:'queue.curMsg',  ko:'현재 대기 인원 {n}명입니다.'},
  ]});

  /* 8. 검증 중 발견한 누락 고정 문구 — 접수/대기/반납/네비/관리/언어 (2026-06-13).
     이모지·기호 접두는 키오스크 DOM 치환이 core 매칭으로 떼어내므로, 여기서는 접두 없는 핵심 문구만 등록. */
  phrases.push({section:'접수·대기·반납·네비·관리 추가 문구', items:[
    {key:'done.come',     ko:'접수 완료! 바로 들어오세요!'},
    {key:'done.wait',     ko:'접수 완료! 호출될 때까지 기다려주세요.'},
    {key:'done.enter',    ko:'호출되면 들어오세요.'},
    {key:'queue.curColon', ko:'현재 대기 인원:'},
    {key:'nav.backArrow', ko:'뒤로가기'},
    {key:'nav.skip',      ko:'건너뛰기'},
    {key:'nav.close',     ko:'닫기'},
    {key:'conn.off',      ko:'미연결'},
    {key:'sym.treatSel',  ko:'증상·처치 선택'},
    {key:'lang.select',   ko:'언어선택 | LANGUAGE'},
    {key:'rental.deadline', ko:'반납 일자'},
    {key:'rental.until',  ko:'까지'},
    {key:'gear.manage',   ko:'키오스크 관리'},
    {key:'gear.fsMax',    ko:'창 최대화'},
    {key:'gear.fsMin',    ko:'창 최소화'},
    {key:'gear.authPh',   ko:'접속 인증키를 입력하세요'},
    /* 온디맨드 명단 fetch 상태 문구 (2026-06-14) */
    {key:'roster.loading', ko:'명단 불러오는 중…'},
    {key:'roster.waiting', ko:'연결을 기다리는 중입니다.'},
    {key:'roster.needNurse', ko:'보건 선생님 프로그램이 켜져 있어야 명단이 표시됩니다.'},
    {key:'roster.searching', ko:'검색 중…'},
  ]});

  return phrases;
}

