  "미연결": {en:"Not connected",zh:"未连接",ja:"未接続",vi:"Chưa kết nối",th:"ยังไม่เชื่อมต่อ",tl:"Hindi nakakonekta",km:"មិនបានភ្ជាប់",mn:"Холбогдоогүй",ru:"Нет связи",ne:"जडान छैन",id:"Tidak terhubung",ar:"غير متصل",ur:"منقطع",es:"Sin conexión"},
  "증상·처치 선택": {en:"Select symptom · treatment",zh:"选择症状·处置",ja:"症状・処置の選択",vi:"Chọn triệu chứng · xử trí",th:"เลือกอาการ·การรักษา",tl:"Pumili ng sintomas · lunas",km:"ជ្រើសរោគសញ្ញា · ការព្យាបាល",mn:"Шинж тэмдэг · эмчилгээ сонгох",ru:"Выбор симптома · помощи",ne:"लक्षण · उपचार छान्नुहोस्",id:"Pilih gejala · penanganan",ar:"اختر العرض · العلاج",ur:"علامت · علاج منتخب کریں",es:"Seleccionar síntoma · tratamiento"},
  "언어선택 | LANGUAGE": {en:"Select Language",zh:"选择语言",ja:"言語選択",vi:"Chọn ngôn ngữ",th:"เลือกภาษา",tl:"Pumili ng Wika",km:"ជ្រើសភាសា",mn:"Хэл сонгох",ru:"Выбор языка",ne:"भाषा छान्नुहोस्",id:"Pilih Bahasa",ar:"اختر اللغة",ur:"زبان منتخب کریں",es:"Seleccionar idioma"},
  "반납 일자": {en:"Return date",zh:"归还日期",ja:"返却日",vi:"Ngày trả",th:"วันที่คืน",tl:"Petsa ng pagsasauli",km:"កាលបរិច្ឆេទសង",mn:"Буцаах огноо",ru:"Дата возврата",ne:"फिर्ता मिति",id:"Tanggal pengembalian",ar:"تاريخ الإرجاع",ur:"واپسی کی تاریخ",es:"Fecha de devolución"},
