  "키오스크 관리": {en:"Kiosk Management",zh:"自助机管理",ja:"キオスク管理",vi:"Quản lý kiosk",th:"การจัดการคีออสก์",tl:"Pamamahala ng Kiosk",km:"ការគ្រប់គ្រង Kiosk",mn:"Киоск удирдлага",ru:"Управление киоском",ne:"किओस्क व्यवस्थापन",id:"Manajemen Kios",ar:"إدارة الكشك",ur:"کیوسک انتظام",es:"Gestión del kiosco"},
