/* 한국어 원문 + 언어코드 → 기본 번역. 없으면 빈 문자열. */
export function kioskGetDefaultTrans(lang, koText){
  const entry = KIOSK_DEFAULT_TRANSLATIONS[(koText||'').trim()];
  return (entry && entry[lang]) ? entry[lang] : '';
}
